    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB0LA_1RC1RD_1LD1RB____1LA | exact ok_iarm0_1_0RB0LA_1RC1RD_1LD1RB____1LA]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB0LA_1RC1RD_1LD1RB____1LA | exact ok_iarm1_0_0RB0LA_1RC1RD_1LD1RB____1LA]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB0LA_1RC1RD_1LD1RB____1LA | exact ok_iarm1_1_0RB0LA_1RC1RD_1LD1RB____1LA]. }
    exfalso; lia.
