(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB0LA_1RC1RD_1LD1RB____1LA : NeverQuasiHaltsTr tm_0RB0LA_1RC1RD_1LD1RB____1LA.
Proof.
  apply (boardph_neverqhtr tm_0RB0LA_1RC1RD_1LD1RB____1LA pins_0RB0LA_1RC1RD_1LD1RB____1LA FAM 1
