Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LC_1LC1LA_0LC1RD_0RB0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_1LC1LA_0LC1RD_0RB0RD
  | 0, 1 => iarm0_1_1RB1LC_1LC1LA_0LC1RD_0RB0RD
  | 1, 0 => iarm1_0_1RB1LC_1LC1LA_0LC1RD_0RB0RD
  | 1, 1 => iarm1_1_1RB1LC_1LC1LA_0LC1RD_0RB0RD
  | _, _ => iarm0_0_1RB1LC_1LC1LA_0LC1RD_0RB0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_1LC1LA_0LC1RD_0RB0RD : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [S1;S1] 1 0 [S1]))
          (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0;S0] 1 0 [S0;S0;S1])) 4 10.
Definition ch_farm1_0_1RB1LC_1LC1LA_0LC1RD_0RB0RD : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 1);RB (SWinR 5);RB (SCycL 2 0);RB (SWin 2)].
