Definition iarm_1RB1RC_1LC1RA____1LD_0RA0LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RC_1LC1RA____1LD_0RA0LD
  | 0, 1 => iarm0_1_1RB1RC_1LC1RA____1LD_0RA0LD
  | 1, 0 => iarm1_0_1RB1RC_1LC1RA____1LD_0RA0LD
  | 1, 1 => iarm1_1_1RB1RC_1LC1RA____1LD_0RA0LD
  | _, _ => iarm0_0_1RB1RC_1LC1RA____1LD_0RA0LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

