  d < fm_b FAM - 1 -> r < 1 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB1RC_1LC1RA____1LD_0RA0LD d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RC_1LC1RA____1LD_0RA0LD | exact ok_iarm0_0_1RB1RC_1LC1RA____1LD_0RA0LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RC_1LC1RA____1LD_0RA0LD | exact ok_iarm0_1_1RB1RC_1LC1RA____1LD_0RA0LD]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RC_1LC1RA____1LD_0RA0LD | exact ok_iarm1_0_1RB1RC_1LC1RA____1LD_0RA0LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RC_1LC1RA____1LD_0RA0LD | exact ok_iarm1_1_1RB1RC_1LC1RA____1LD_0RA0LD]. }
    exfalso; lia.
