(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1RC_1LC1RA____1LD_0RA0LD : NeverQuasiHaltsTr tm_1RB1RC_1LC1RA____1LD_0RA0LD.
Proof.
  apply (boardph_neverqhtr tm_1RB1RC_1LC1RA____1LD_0RA0LD pins_1RB1RC_1LC1RA____1LD_0RA0LD FAM 1
                           iarm_1RB1RC_1LC1RA____1LD_0RA0LD 1 1
                           farm_1RB1RC_1LC1RA____1LD_0RA0LD 1 1
                           fm1_1RB1RC_1LC1RA____1LD_0RA0LD fm2_1RB1RC_1LC1RA____1LD_0RA0LD 0 vis_1RB1RC_1LC1RA____1LD_0RA0LD
                           [1] 0 3).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
