    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1RC_1LC1RA____1LD_0RA0LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB1RC_1LC1RA____1LD_0RA0LD.
  - lia.
  - exact iarm_sound_1RB1RC_1LC1RA____1LD_0RA0LD.
  - exact iarm_lhs_1RB1RC_1LC1RA____1LD_0RA0LD.
  - exact iarm_rhs_1RB1RC_1LC1RA____1LD_0RA0LD.
  - exact iarm_cb_1RB1RC_1LC1RA____1LD_0RA0LD.
  - lia.
  - lia.
  - exact farm_sound_1RB1RC_1LC1RA____1LD_0RA0LD.
  - exact farm_lhs_1RB1RC_1LC1RA____1LD_0RA0LD.
